import java.util.*;

class Solution {
    public int[][] fuseSlots(int[][] slots) {
        if (slots.length == 0) return new int[0][];
        int[][] s = slots.clone();
        Arrays.sort(s, (a, b) -> Integer.compare(a[0], b[0]));   // order by start
        List<int[]> out = new ArrayList<>();
        int curStart = s[0][0], curEnd = s[0][1];
        for (int i = 1; i < s.length; i++) {
            if (s[i][0] <= curEnd) {                    // overlaps or touches: extend
                curEnd = Math.max(curEnd, s[i][1]);
            } else {                                    // gap: close current block
                out.add(new int[]{curStart, curEnd});
                curStart = s[i][0];
                curEnd = s[i][1];
            }
        }
        out.add(new int[]{curStart, curEnd});
        return out.toArray(new int[0][]);
    }
}

