function fuseSlots(slots) {
  const a = slots.map(x => x.slice()).sort((p, q) => p[0] - q[0] || p[1] - q[1]);
  const out = [];
  for (const [s, e] of a) {
    if (out.length && s <= out[out.length - 1][1]) out[out.length - 1][1] = Math.max(out[out.length - 1][1], e);
    else out.push([s, e]);
  }
  return out;
}
